import React from 'react';
import { ChevronRight, Star } from 'lucide-react';
import StarRating from './StarRating';

const BeerCard = ({ beer, onClick }) => (
  <div 
    className="group bg-white rounded-2xl shadow-md hover:shadow-xl transition-all duration-300 cursor-pointer transform hover:-translate-y-1 border border-gray-100 overflow-hidden"
    onClick={() => onClick(beer)}
  >
    {/* Header with brewery name */}
    <div className="bg-gradient-to-r from-red-50 to-orange-50 px-6 py-4 border-b border-gray-100">
      <p className="text-red-600 font-semibold text-sm uppercase tracking-wide">{beer.brewery}</p>
    </div>

    <div className="p-6">
      {/* Beer name */}
      <h3 className="font-bold text-xl text-gray-900 mb-3 group-hover:text-red-600 transition-colors duration-200">
        {beer.name}
      </h3>
      
      {/* Beer details grid */}
      <div className="grid grid-cols-2 gap-3 mb-4">
        <div className="bg-gray-50 p-3 rounded-xl text-center">
          <div className="text-xs text-gray-500 mb-1">Style</div>
          <div className="text-sm font-semibold text-gray-900">{beer.style}</div>
        </div>
        <div className="bg-gray-50 p-3 rounded-xl text-center">
          <div className="text-xs text-gray-500 mb-1">ABV</div>
          <div className="text-sm font-semibold text-gray-900">{beer.abv}%</div>
        </div>
      </div>

      {/* IBU if available */}
      {beer.ibu && (
        <div className="bg-gray-50 p-3 rounded-xl mb-4 text-center">
          <div className="text-xs text-gray-500 mb-1">IBU</div>
          <div className="text-sm font-semibold text-gray-900">{beer.ibu}</div>
        </div>
      )}
      
      {/* Rating section */}
      <div className="border-t border-gray-100 pt-4 space-y-3">
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium text-gray-600">Community Rating</span>
          <div className="flex items-center gap-2">
            <div className="flex items-center">
              {[1, 2, 3, 4, 5].map((star) => (
                <Star
                  key={star}
                  className={`w-4 h-4 ${
                    star <= (beer.averageRating || 0)
                      ? 'text-yellow-400 fill-yellow-400' 
                      : 'text-gray-300'
                  }`}
                />
              ))}
            </div>
            <span className="text-sm font-semibold text-gray-700">
              {beer.averageRating ? beer.averageRating.toFixed(1) : '0.0'}
            </span>
          </div>
        </div>
        
        <div className="flex items-center justify-between">
          <span className="text-sm text-gray-500">
            {beer.totalReviews || 0} review{(beer.totalReviews || 0) !== 1 ? 's' : ''}
          </span>
          <ChevronRight className="w-4 h-4 text-red-500 group-hover:translate-x-1 transition-transform duration-200" />
        </div>
      </div>
    </div>
  </div>
);

export default BeerCard;
